-- NOW-or-NEVER — COMPLETE OFFICIAL NEET (UG) 2026 SYLLABUS SEED
-- Source: NMC UGMEB syllabus, published by NTA
-- Official notice: https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf
-- Finalized by UGMEB: 2025-12-22
-- This file seeds the complete Physics (20), Chemistry (20), Biology (10) units.

begin;

insert into public.neet_syllabus
(exam_type,exam_year,subject,unit_code,unit_name,chapter,scope_text,exclusions_text,source_name,source_url,source_date,active)
values
('NEET',2026,'Physics','UNIT_1','Physics and Measurement','Physics and Measurement','Units of measurements; system of units; SI units; fundamental and derived units; least count; significant figures; errors in measurements; dimensions of physical quantities; dimensional analysis and its applications.','Questions must remain within the listed measurement, error, significant-figure and dimensional-analysis scope.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_2','Kinematics','Kinematics','The frame of reference; motion in a straight line; position-time graph; speed and velocity; uniform and non-uniform motion; average speed and instantaneous velocity; uniformly accelerated motion; velocity-time and position-time graphs; relations for uniformly accelerated motion; scalars and vectors; vector addition and subtraction; scalar and vector products; unit vector; resolution of a vector; relative velocity; motion in a plane; projectile motion; uniform circular motion.','No advanced mechanics beyond the listed kinematics topics.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_3','Laws of Motion','Laws of Motion','Force and inertia; Newtons First law; momentum; Newtons Second Law; impulse; Newtons Third Law; conservation of linear momentum and applications; equilibrium of concurrent forces; static and kinetic friction; laws of friction; rolling friction; dynamics of uniform circular motion; centripetal force; vehicle on level circular road; vehicle on banked road.','Keep questions within Newtonian laws, momentum, friction, equilibrium and listed circular-motion applications.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_4','Work, Energy, and Power','Work, Energy, and Power','Work done by a constant force and a variable force; kinetic and potential energies; work-energy theorem; power; potential energy of a spring; conservation of mechanical energy; conservative and non-conservative forces; motion in a vertical circle; elastic and inelastic collisions in one and two dimensions.','No advanced analytical mechanics.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_5','Rotational Motion','Rotational Motion','Centre of mass of a two-particle system; centre of mass of a rigid body; basic concepts of rotational motion; moment of a force; torque; angular momentum; conservation of angular momentum and applications; moment of inertia; radius of gyration; moments of inertia for simple geometrical objects; parallel and perpendicular axes theorems and applications; equilibrium of rigid bodies; rigid-body rotation; equations of rotational motion; comparison of linear and rotational motions.','Use only the listed rotational-motion principles and standard simple-body moments of inertia.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_6','Gravitation','Gravitation','Universal law of gravitation; acceleration due to gravity and its variation with altitude and depth; Keplers law of planetary motion; gravitational potential energy; gravitational potential; escape velocity; motion of a satellite; orbital velocity; time period and energy of a satellite.','No advanced celestial mechanics beyond the listed laws and satellite relations.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_7','Properties of Solids and Liquids','Properties of Solids and Liquids','Elastic behaviour; stress-strain relationship; Hookes law; Youngs modulus; bulk modulus; modulus of rigidity; pressure due to a fluid column; Pascals law and applications; effect of gravity on fluid pressure; viscosity; Stokes law; terminal velocity; streamline and turbulent flow; critical velocity; Bernoullis principle and applications; surface energy and surface tension; angle of contact; excess pressure across a curved surface; drops, bubbles and capillary rise; heat and temperature; thermal expansion; specific heat capacity; calorimetry; change of state; latent heat; heat transfer by conduction, convection and radiation.','No fluid or thermal physics beyond the listed syllabus.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_8','Thermodynamics','Thermodynamics','Thermal equilibrium; zeroth law of thermodynamics; concept of temperature; heat; work; internal energy; first law of thermodynamics; isothermal and adiabatic processes; second law of thermodynamics; reversible and irreversible processes.','No advanced statistical thermodynamics.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_9','Kinetic Theory of Gases','Kinetic Theory of Gases','Equation of state of a perfect gas; work done on compressing a gas; assumptions of kinetic theory; concept of pressure; kinetic interpretation of temperature; RMS speed; degrees of freedom; law of equipartition of energy and applications to specific heat capacities of gases; mean free path; Avogadros number.','No advanced molecular-statistical treatment beyond the listed elementary kinetic theory.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_10','Oscillations and Waves','Oscillations and Waves','Oscillations and periodic motion; time period; frequency; displacement as a function of time; periodic functions; simple harmonic motion and equation; phase; spring oscillations; restoring force and force constant; energy in SHM; kinetic and potential energies; simple pendulum and derivation of time period; wave motion; longitudinal and transverse waves; speed of travelling wave; displacement relation for progressive wave; superposition; reflection; standing waves in strings and organ pipes; fundamental mode and harmonics; beats.','No advanced wave mechanics beyond the listed classical oscillation and wave topics.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_11','Electrostatics','Electrostatics','Electric charges and conservation of charge; Coulombs law and forces between point charges; forces between multiple charges; superposition; continuous charge distribution; electric field due to point charge; electric field lines; electric dipole; field due to dipole; torque on dipole in uniform field; electric flux; Gauss law and applications to infinitely long uniformly charged straight wire, uniformly charged infinite plane sheet and uniformly charged thin spherical shell; electric potential and calculation for point charge, dipole and system of charges; potential difference; equipotential surfaces; electrical potential energy of two point charges and electric dipole; conductors and insulators; dielectrics and electric polarization; capacitors and capacitance; series and parallel capacitors; parallel-plate capacitor with and without dielectric; energy stored in capacitor.','Questions should use standard NEET electrostatics relations and the explicitly listed Gauss-law geometries.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_12','Current Electricity','Current Electricity','Electric current; drift velocity; mobility and relation with current; Ohms law; electrical resistance; V-I characteristics of Ohmic and non-ohmic conductors; electrical energy and power; resistivity and conductivity; series and parallel combinations of resistors; temperature dependence of resistance; internal resistance; potential difference and emf of a cell; cells in series and parallel; Kirchhoffs laws and applications; Wheatstone bridge; metre bridge.','No advanced semiconductor transport theory in this unit.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_13','Magnetic Effects of Current and Magnetism','Magnetic Effects of Current and Magnetism','Biot-Savart law and application to current-carrying circular loop; Ampere law and applications to infinitely long current-carrying straight wire and solenoid; force on moving charge in uniform magnetic and electric fields; force on current-carrying conductor in uniform magnetic field; force between two parallel current-carrying conductors and definition of ampere; torque on current loop in uniform magnetic field; moving-coil galvanometer, sensitivity and conversion to ammeter and voltmeter; current loop as magnetic dipole and magnetic dipole moment; bar magnet as equivalent solenoid; magnetic field lines; field due to magnetic dipole along and perpendicular to axis; torque on magnetic dipole; para-, dia- and ferromagnetic substances with examples; effect of temperature on magnetic properties.','No advanced magnetism or electromagnetic field theory beyond the listed applications.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_14','Electromagnetic Induction and Alternating Currents','Electromagnetic Induction and Alternating Currents','Electromagnetic induction; Faradays law; induced emf and current; Lenz law; eddy currents; self and mutual inductance; alternating current; peak and RMS values of AC current and voltage; reactance and impedance; LCR series circuit; resonance; power in AC circuits; wattless current; AC generator; transformer.','No advanced electromagnetic-wave or field-theory mathematics beyond this unit.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_15','Electromagnetic Waves','Electromagnetic Waves','Displacement current; electromagnetic waves and characteristics; transverse nature of electromagnetic waves; electromagnetic spectrum including radio waves, microwaves, infrared, visible, ultraviolet, X-rays and gamma rays; applications of electromagnetic waves.','No advanced wave propagation theory.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_16','Optics','Optics','Reflection of light; spherical mirrors; mirror formula; refraction at plane and spherical surfaces; thin-lens formula; lens-maker formula; total internal reflection and applications; magnification; power of a lens; combination of thin lenses in contact; prism; microscope and astronomical telescope, reflecting and refracting, and magnifying powers; wave optics; wavefront; Huygens principle; laws of reflection and refraction using Huygens principle; interference; Youngs double-slit experiment and fringe width; coherent sources and sustained interference; single-slit diffraction and central maximum; polarization; plane-polarized light; Brewsters law; uses of plane-polarized light and Polaroid.','No advanced Fourier optics or modern optical engineering.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_17','Dual Nature of Matter and Radiation','Dual Nature of Matter and Radiation','Dual nature of radiation; photoelectric effect; Hertz and Lenard observations; Einstein photoelectric equation; particle nature of light; matter waves; wave nature of particles; de Broglie relation.','No advanced quantum mechanics beyond photoelectric effect and de Broglie relation.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_18','Atoms and Nuclei','Atoms and Nuclei','Alpha-particle scattering experiment; Rutherford model; Bohr model; energy levels; hydrogen spectrum; composition and size of nucleus; atomic masses; mass-energy relation; mass defect; binding energy per nucleon and variation with mass number; nuclear fission and fusion.','No advanced nuclear physics beyond the listed models and processes.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_19','Electronic Devices','Electronic Devices','Semiconductors; semiconductor diode; I-V characteristics in forward and reverse bias; diode as rectifier; LED; photodiode; solar cell; Zener diode; Zener diode as voltage regulator; logic gates OR, AND, NOT, NAND and NOR.','No advanced semiconductor device physics or digital electronics beyond the listed devices and gates.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Physics','UNIT_20','Experimental Skills','Experimental Skills','Basic approach and observations of experiments and activities: Vernier calipers for internal/external diameter and depth; screw gauge for thickness/diameter; simple pendulum and energy dissipation graph; metre scale and principle of moments; Youngs modulus of metallic wire; surface tension by capillary rise and effect of detergents; coefficient of viscosity by terminal velocity; speed of sound using resonance tube; specific heat by method of mixtures; resistivity using metre bridge; resistance using Ohms law; resistance and figure of merit of galvanometer by half-deflection; focal length of convex mirror, concave mirror and convex lens using parallax; deviation versus incidence for triangular prism; refractive index of glass slab using travelling microscope; characteristic curves of p-n junction diode; characteristic curves of Zener diode and reverse breakdown voltage; identification of diode, LED, resistor and capacitor.','Experimental questions should remain at the basic approach, observation and interpretation level stated by the official syllabus.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),

-- ========================= CHEMISTRY =========================
('NEET',2026,'Chemistry','UNIT_1','Some Basic Concepts in Chemistry','Some Basic Concepts in Chemistry','Matter and its nature; Dalton atomic theory; concept of atom, molecule, element and compound; laws of chemical combination; atomic and molecular masses; mole concept; molar mass; percentage composition; empirical and molecular formulae; chemical equations and stoichiometry.','No advanced physical chemistry beyond mole concept and stoichiometry listed here.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_2','Atomic Structure','Atomic Structure','Nature of electromagnetic radiation; photoelectric effect; hydrogen spectrum; Bohr model and postulates; derivation of energy and radius relations; limitations of Bohr model; dual nature of matter; de Broglie relationship; Heisenberg uncertainty principle; elementary ideas of quantum mechanics; quantum mechanical model; atomic orbitals as one-electron wave functions; variation of psi and psi-squared with r for 1s and 2s; principal, angular momentum and magnetic quantum numbers; shapes of s, p and d orbitals; electron spin; Aufbau principle; Pauli exclusion principle; Hund rule; electronic configuration; extra stability of half-filled and completely filled orbitals.','Keep quantum mechanics at the elementary level stated in the syllabus.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_3','Chemical Bonding and Molecular Structure','Chemical Bonding and Molecular Structure','Kossel-Lewis approach; ionic and covalent bonds; formation and factors affecting ionic bonds; lattice enthalpy; electronegativity; Fajans rule; dipole moment; VSEPR theory and shapes of simple molecules; valence bond theory; hybridization involving s, p and d orbitals; resonance; molecular orbital theory; LCAOs; bonding and antibonding orbitals; sigma and pi bonds; MO configurations of homonuclear diatomic molecules; bond order, bond length and bond energy; elementary metallic bonding; hydrogen bonding and applications.','No advanced computational or quantum-chemical treatment.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_4','Chemical Thermodynamics','Chemical Thermodynamics','Fundamentals of thermodynamics; system and surroundings; extensive and intensive properties; state functions; types of processes; first law; work, heat, internal energy and enthalpy; heat capacity and molar heat capacity; Hess law; enthalpies of bond dissociation, combustion, formation, atomization, sublimation, phase transition, hydration, ionization and solution; second law; spontaneity; entropy change of universe; Gibbs energy as criterion for spontaneity; standard Gibbs energy change and equilibrium constant.','No advanced thermodynamic formalism beyond the listed concepts.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_5','Solutions','Solutions','Concentration expressions: molality, molarity, mole fraction, percentage by volume and mass; vapour pressure and Raoult law; ideal and non-ideal solutions; vapour-pressure composition plots; colligative properties; relative lowering of vapour pressure; depression of freezing point; elevation of boiling point; osmotic pressure; molecular mass from colligative properties; abnormal molar mass; van’t Hoff factor and significance.','No advanced solution thermodynamics.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_6','Equilibrium','Equilibrium','Dynamic equilibrium; physical equilibria solid-liquid, liquid-gas and solid-gas; Henry law; characteristics of physical equilibrium; chemical equilibrium; law of chemical equilibrium; Kp and Kc; significance of Gibbs energy and standard Gibbs energy; factors affecting equilibrium; concentration, pressure, temperature and catalyst; Le Chatelier principle; ionic equilibrium; weak and strong electrolytes; ionization; Arrhenius, Bronsted-Lowry and Lewis acids and bases; acid-base equilibria including multistage ionization; ionization constants; ionization of water; pH; common-ion effect; salt hydrolysis and pH; sparingly soluble salts and solubility products; buffer solutions.','No advanced equilibrium theory beyond the listed equilibrium concepts.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_7','Redox Reactions and Electrochemistry','Redox Reactions and Electrochemistry','Electronic concepts of oxidation and reduction; redox reactions; oxidation number and rules; balancing redox reactions; electrolytic and metallic conduction; conductance in electrolytic solutions; molar conductivities and variation with concentration; Kohlrausch law and applications; electrochemical cells; electrolytic and galvanic cells; electrodes; electrode potentials including standard potential; half-cell and cell reactions; emf of galvanic cell; Nernst equation and applications; relation between cell potential and Gibbs energy; dry cell; lead accumulator; fuel cells.','No advanced electrochemical kinetics or materials science.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_8','Chemical Kinetics','Chemical Kinetics','Rate of reaction; factors affecting rate: concentration, temperature, pressure and catalyst; elementary and complex reactions; order and molecularity; rate law; rate constant and units; differential and integral forms of zero- and first-order reactions; characteristics and half-lives; effect of temperature; Arrhenius theory; activation energy and calculation; collision theory of bimolecular gaseous reactions, no derivation.','Collision theory must remain at the no-derivation level stated in the official syllabus.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_9','Classification of Elements and Periodicity in Properties','Classification of Elements and Periodicity in Properties','Modern periodic law and present periodic table; s, p, d and f block elements; periodic trends in atomic and ionic radii, ionization enthalpy, electron gain enthalpy, valence, oxidation states and chemical reactivity.','No advanced periodic-property models beyond listed trends.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_10','P-Block Elements','P-Block Elements','Groups 13 to 18; general introduction; electronic configuration; general trends in physical and chemical properties across periods and down groups; unique behaviour of first element in each group.','Keep p-block questions within the stated general trends and first-element behaviour scope.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_11','d- and f-Block Elements','d- and f-Block Elements','Transition elements: general introduction, electronic configuration, occurrence and characteristics; trends in first-row transition elements including physical properties, ionization enthalpy, oxidation states, atomic radii, colour, catalytic behaviour, magnetic properties, complex formation, interstitial compounds and alloy formation; preparation, properties and uses of K2Cr2O7 and KMnO4; inner transition elements; lanthanoids: electronic configuration, oxidation states and lanthanoid contraction; actinoids: electronic configuration and oxidation states.','No advanced coordination or solid-state theory beyond the stated scope.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_12','Coordination Compounds','Coordination Compounds','Introduction to coordination compounds; Werner theory; ligands; coordination number; denticity; chelation; IUPAC nomenclature of mononuclear coordination compounds; isomerism; bonding using valence-bond approach and basic ideas of crystal field theory; colour and magnetic properties; importance in qualitative analysis, extraction of metals and biological systems.','Crystal-field treatment must remain at the basic-idea level specified by the syllabus.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_13','Purification and Characterisation of Organic Compounds','Purification and Characterisation of Organic Compounds','Purification by crystallization, sublimation, distillation, differential extraction and chromatography; qualitative analysis for nitrogen, sulphur, phosphorus and halogens; quantitative analysis basic principles; estimation of carbon, hydrogen, nitrogen, halogens, sulphur and phosphorus; empirical and molecular formula calculations; numerical problems in organic quantitative analysis.','Quantitative analysis remains at basic principles and numerical problems stated in the syllabus.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_14','Some Basic Principles of Organic Chemistry','Some Basic Principles of Organic Chemistry','Tetravalency of carbon; shapes of simple molecules; hybridization s and p; classification of organic compounds by functional groups and those containing halogens, oxygen, nitrogen and sulphur; homologous series; structural and stereoisomerism; trivial and IUPAC nomenclature; homolytic and heterolytic bond fission; free radicals, carbocations and carbanions; stability of carbocations and free radicals; electrophiles and nucleophiles; inductive, electromeric, resonance and hyperconjugation effects; substitution, addition, elimination and rearrangement reactions.','No advanced organic reaction mechanisms beyond those explicitly listed.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_15','Hydrocarbons','Hydrocarbons','Classification, isomerism, IUPAC nomenclature, general methods of preparation, properties and reactions; alkanes and conformations using sawhorse and Newman projections of ethane; halogenation mechanism; alkenes and geometrical isomerism; electrophilic addition; addition of hydrogen, halogens, water and hydrogen halides; Markownikoff and peroxide effect; ozonolysis; polymerization; alkynes and acidic character; addition reactions and polymerization; aromatic hydrocarbons; benzene structure and aromaticity; electrophilic substitution; halogenation; nitration; Friedel-Crafts alkylation and acylation; directive influence of functional group in monosubstituted benzene.','No advanced aromaticity or reaction theory beyond listed reactions and mechanisms.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_16','Organic Compounds Containing Halogens','Organic Compounds Containing Halogens','General methods of preparation, properties and reactions; nature of C-X bond; mechanisms of substitution reactions; uses; environmental effects of chloroform, iodoform, freons and DDT.','Questions must stay within the listed compounds, reactions and environmental effects.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_17','Organic Compounds Containing Oxygen','Organic Compounds Containing Oxygen','General methods of preparation, properties, reactions and uses; alcohols, phenols and ethers; primary, secondary and tertiary alcohol identification; dehydration mechanism; phenols acidic nature and electrophilic substitution including halogenation, nitration and sulphonation; Reimer-Tiemann reaction; ethers structure; aldehydes and ketones: carbonyl group, nucleophilic addition, relative reactivity, HCN, ammonia and derivatives, Grignard reagent, oxidation, reduction by Wolff-Kishner and Clemmensen, alpha-hydrogen acidity, aldol condensation, Cannizzaro reaction, haloform reaction and tests distinguishing aldehydes and ketones; carboxylic acids, acidic strength and factors affecting it.','No advanced carbonyl chemistry beyond the listed reactions and tests.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_18','Organic Compounds Containing Nitrogen','Organic Compounds Containing Nitrogen','General methods of preparation; properties, reactions and uses; amines: nomenclature, classification, structure, basic character, identification of primary, secondary and tertiary amines and basic character; diazonium salts and importance in synthetic organic chemistry.','No advanced nitrogen chemistry beyond listed amines and diazonium salts.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_19','Biomolecules','Biomolecules','General introduction and importance of biomolecules; carbohydrates and classification; aldoses and ketoses; glucose and fructose; constituent monosaccharides of sucrose, lactose and maltose; proteins; elementary idea of alpha-amino acids; peptide bond; polypeptides; primary, secondary, tertiary and quaternary protein structure, qualitative idea only; denaturation; enzymes; vitamins and classification/functions; nucleic acids and chemical constitution of DNA and RNA; biological functions of nucleic acids; hormones, general introduction.','Protein structural treatment must remain qualitative as stated.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Chemistry','UNIT_20','Principles Related to Practical Chemistry','Principles Related to Practical Chemistry','Detection of nitrogen, sulphur and halogens in organic compounds; detection of hydroxyl alcoholic and phenolic, carbonyl aldehyde and ketone, carboxyl and amino groups; chemistry involved in preparation of Mohrs salt and potash alum; acetanilide, p-nitroacetanilide, aniline yellow and iodoform; titrimetric chemistry involving acids, bases and indicators, oxalic acid versus KMnO4 and Mohrs salt versus KMnO4; qualitative salt analysis principles for cations Pb2+, Cu2+, Al3+, Fe3+, Zn2+, Ni2+, Ca2+, Ba2+, Mg2+, NH4+ and anions CO3 2-, S2-, SO3 2-, NO3-, NO2-, Cl-, Br-, I- with insoluble salts excluded; principles of experiments on enthalpy of solution of CuSO4, enthalpy of neutralization of strong acid and strong base, lyophilic and lyophobic sols, and kinetic study of iodide ions with hydrogen peroxide at room temperature.','Insoluble salts are explicitly excluded from the listed qualitative salt analysis. Keep practical questions at principle/observation level.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),

-- ========================= BIOLOGY =========================
('NEET',2026,'Biology','UNIT_1','Diversity in Living World','Diversity in Living World','What is living; biodiversity; need for classification; taxonomy and systematics; concept of species and taxonomical hierarchy; binomial nomenclature; five-kingdom classification; salient features and classification of Monera, Protista and Fungi into major groups; lichens; viruses and viroids; salient features and classification of plants into Algae, Bryophytes, Pteridophytes and Gymnosperms with three to five salient distinguishing features and at least two examples each; salient features and classification of animals, non-chordates up to phyla level and chordates up to classes level with three to five salient features and at least two examples.','Animal classification should not go below the stated levels unless necessary for a listed example.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Biology','UNIT_2','Structural Organisation in Animals and Plants','Structural Organisation in Animals and Plants','Morphology and modifications; tissues; anatomy and functions of different parts of flowering plants including root, stem, leaf, inflorescence cymose and racemose, flower, fruit and seed; relevant families Malvaceae, Cruciferae, Leguminoceae, Compositae and Graminae; animal tissues; morphology, anatomy and functions of digestive, circulatory, respiratory, nervous and reproductive systems of an insect/frog as stated in the official syllabus, brief account only.','Plant-family and animal-system questions must remain at the brief level specified in the official syllabus.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Biology','UNIT_3','Cell Structure and Function','Cell Structure and Function','Cell theory and cell as basic unit of life; prokaryotic and eukaryotic cell; plant and animal cell; cell envelope, membrane and wall; cell organelles and functions; endomembrane system including endoplasmic reticulum, Golgi bodies, lysosomes and vacuoles; mitochondria, ribosomes, plastids, microbodies; cytoskeleton, cilia, flagella, centrioles with ultrastructure and function; nucleus, nuclear membrane, chromatin and nucleolus; chemical constituents of living cells; biomolecules including proteins, carbohydrates, lipids and nucleic acids; enzymes including types, properties, action, classification and nomenclature; cell division, cell cycle, mitosis and meiosis and significance.','No advanced cell biology or molecular pathways beyond the listed structures, biomolecules, enzymes and division.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Biology','UNIT_4','Plant Physiology','Plant Physiology','Photosynthesis as autotrophic nutrition; site of photosynthesis; pigments, elementary idea; photochemical and biosynthetic phases; cyclic and non-cyclic photophosphorylation; chemiosmotic hypothesis; photorespiration; C3 and C4 pathways; factors affecting photosynthesis; respiration and gas exchange; cellular respiration including glycolysis, fermentation, TCA cycle and electron transport system; energy relations and number of ATP molecules generated; amphibolic pathways; respiratory quotient; plant growth and development including seed germination, phases and growth rate, conditions of growth, differentiation, dedifferentiation and redifferentiation, developmental sequence and plant growth regulators auxin, gibberellin, cytokinin, ethylene and ABA.','Keep biochemical detail at the level explicitly indicated by the official syllabus.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Biology','UNIT_5','Human Physiology','Human Physiology','Breathing and respiration; respiratory organs in animals, recall only; human respiratory system; mechanism and regulation of breathing; gas exchange and transport; respiratory volumes; asthma, emphysema and occupational respiratory disorders. Body fluids and circulation: blood composition, blood groups, coagulation; lymph; human circulatory system; heart and blood vessels; cardiac cycle, cardiac output, ECG, double circulation, regulation of cardiac activity; hypertension, coronary artery disease, angina pectoris and heart failure. Excretion: ammonotelism, ureotelism, uricotelism; human excretory system; urine formation; osmoregulation; renin-angiotensin, atrial natriuretic factor and ADH; diabetes insipidus; other organs in excretion; uraemia, renal failure, renal calculi, nephritis, dialysis and artificial kidney. Locomotion: ciliary, flagellar and muscular movement; skeletal muscle, contractile proteins and contraction; skeletal system and functions; joints; myasthenia gravis, tetany, muscular dystrophy, arthritis, osteoporosis and gout. Neural control: neuron and nerves; CNS, PNS and visceral nervous system; generation and conduction of nerve impulse. Chemical coordination: endocrine glands and hormones; hypothalamus, pituitary, pineal, thyroid, parathyroid, adrenal, pancreas and gonads; elementary hormone action; hormones as messengers and regulators; hypo- and hyperactivity and related common disorders including dwarfism, acromegaly, cretinism, goiter, exophthalmic goiter, diabetes and Addisons disease. Diseases/disorders are to be dealt with briefly.','Diseases and disorders named by the syllabus are brief-account topics; do not introduce unrelated clinical detail.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Biology','UNIT_6','Reproduction','Reproduction','Sexual reproduction in flowering plants: flower structure; male and female gametophytes; pollination types, agencies and examples; outbreeding devices; pollen-pistil interaction; double fertilization; post-fertilization events including endosperm and embryo development, seed and fruit formation; apomixis, parthenocarpy and polyembryony; significance of seed and fruit. Human reproduction: male and female reproductive systems; microscopic anatomy of testis and ovary; spermatogenesis and oogenesis; menstrual cycle; fertilisation; embryo development up to blastocyst; implantation; pregnancy and placenta formation, elementary idea; parturition, elementary idea; lactation, elementary idea. Reproductive health: need and prevention of STDs; birth control, contraception and MTP; amniocentesis; infertility and ART including IVF, ZIFT and GIFT, elementary idea for general awareness.','ART topics marked elementary idea must not be expanded into advanced reproductive medicine.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Biology','UNIT_7','Genetics and Evolution','Principles of Inheritance and Variation','Heredity and variation; Mendelian inheritance; incomplete dominance; co-dominance; multiple alleles and inheritance of blood groups; pleiotropy; elementary idea of polygenic inheritance; chromosome theory of inheritance; chromosomes and genes; sex determination in humans, birds and honey bee; linkage and crossing over; sex-linked inheritance including haemophilia and colour blindness; Mendelian disorder thalassemia; chromosomal disorders Down syndrome, Turner syndrome and Klinefelter syndrome.','No XIST mechanism, Robertsonian translocation mechanics, FMR1 molecular mechanisms, detailed repeat-expansion mechanisms, advanced cytogenetics, population genetics or unrelated genetic disorders in this chapter. Such topics belong only where explicitly covered by another official scope.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Biology','UNIT_7','Genetics and Evolution','Molecular Basis of Inheritance','Search for genetic material and DNA as genetic material; structure of DNA and RNA; DNA packaging; DNA replication; central dogma; transcription; genetic code; translation; gene expression and regulation including Lac Operon; genome and Human Genome Project; DNA fingerprinting; protein biosynthesis.','No advanced genomics, epigenomics, CRISPR, advanced chromatin biology, advanced transcriptomics, clinical molecular genetics or research-level molecular biology unless explicitly added by a future official syllabus.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Biology','UNIT_7','Genetics and Evolution','Evolution','Origin of life; biological evolution and evidences from palaeontology, comparative anatomy, embryology and molecular evidence; Darwins contribution; Modern Synthetic theory of Evolution; mechanisms including variation by mutation and recombination and natural selection with examples; types of natural selection; gene flow and genetic drift; Hardy-Weinberg principle; adaptive radiation; human evolution.','Hardy-Weinberg, gene flow and genetic drift are explicitly allowed here and must not be globally blocked by the validator. Keep calculations and concepts at NEET level.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Biology','UNIT_8','Biology and Human Welfare','Biology and Human Welfare','Health and disease; pathogens; parasites causing human diseases including malaria, filariasis, ascariasis, typhoid, pneumonia, common cold, amoebiasis, ringworm, dengue and chikungunya; basic concepts of immunology and vaccines; cancer; HIV and AIDS; adolescence; drug and alcohol abuse; tobacco abuse; microbes in human welfare including household food processing, industrial production, sewage treatment, energy generation, biocontrol agents and biofertilizers.','No advanced clinical medicine or pharmacology beyond the named diseases, basic immunology and welfare applications.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Biology','UNIT_9','Biotechnology and Its Applications','Biotechnology and Its Applications','Principles and process of biotechnology; genetic engineering and recombinant DNA technology; applications in health and agriculture including human insulin and vaccine production, gene therapy; genetically modified organisms and Bt crops; transgenic animals; biosafety issues including biopiracy and patents.','No advanced biotechnology beyond the listed recombinant-DNA applications and biosafety topics.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true),
('NEET',2026,'Biology','UNIT_10','Ecology and Environment','Ecology and Environment','Organisms and environment; population interactions including mutualism, competition, predation and parasitism; population attributes including growth, birth rate, death rate and age distribution; ecosystem patterns and components; productivity and decomposition; energy flow; pyramids of number, biomass and energy; biodiversity and conservation including concept, patterns, importance, loss, conservation, hotspots, endangered organisms, extinction, Red Data Book, biosphere reserves, national parks, sanctuaries and sacred groves.','No advanced ecological modelling beyond the listed population, ecosystem and biodiversity concepts.','National Medical Commission (NMC)','https://nta.ac.in/Download/Notice/Notice_20260108180635.pdf','2025-12-22',true)

on conflict (exam_year,subject,unit_code,chapter)
do update set
  unit_name=excluded.unit_name,
  scope_text=excluded.scope_text,
  exclusions_text=excluded.exclusions_text,
  source_name=excluded.source_name,
  source_url=excluded.source_url,
  source_date=excluded.source_date,
  active=true,
  updated_at=now();

commit;

